CREATE OR REPLACE FUNCTION public.minhas_permissoes() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(c),'{}') FROM unnest(ARRAY['admin.usuarios','admin.perfis','avisos.publicar','avisos.gerenciar','avisos.insider','avisos.confirmacao','conteudo.editar','documentos.gerenciar','formularios.gerenciar','pendencias.liderados']) c WHERE public.usuario_tem_permissao(auth.uid(),c); $$;